    if a.Z<=0.01 and b.Z<=0.01 then return end
    if a.Z<=0.01 then
        from=from+(to-from)*((0.02-a.Z)/(b.Z-a.Z))
        a=camera:WorldToViewportPoint(from)
    elseif b.Z<=0.01 then
        to=from+(to-from)*((0.02-a.Z)/(b.Z-a.Z))
        b=camera:WorldToViewportPoint(to)
    end
